import re, glob

files = sorted(glob.glob('draft/*.md')) + sorted(glob.glob('figures/*.md'))
bad = ['TODO', 'TBD', 'XXX', 'placeholder', 'Placeholder', 'draftsperson', 'confirm', 'insert ']
for f in files:
    t = open(f).read()
    if '—' in t or '–' in t:
        print('DASH', f)
    for b in bad:
        if b in t:
            print('MARKER', f, repr(b))

tab = open('draft/numerals.md').read()
nums = dict(re.findall(r'\|\s*(\d+)\s*\|\s*([^|]+?)\s*\|', tab))
print('table', sorted(int(k) for k in nums))
used = {}
for f in files:
    if f.endswith('numerals.md'):
        continue
    t = open(f).read()
    for n in re.findall(r'\b(\d{1,3})\b', t):
        used.setdefault(n, set()).add(f)
print('used not in table:', {n: sorted(v) for n, v in used.items() if n not in nums})
print('table not used:', [n for n in nums if n not in used])

a = open('draft/10-abstract.md').read().split()
print('abstract words', len(a))
for f in glob.glob('figures/*.md'):
    print(f, len(open(f).read()))

