import re,glob,os
nums=set()
for line in open('draft/numerals.md'):
    m=re.match(r'\|\s*(\d+)\s*\|\s*(.+?)\s*\|',line)
    if m: nums.add(m.group(1))
print("table:",sorted(nums,key=int))
for f in sorted(glob.glob('figures/*.md')):
    t=open(f).read()
    body=t.split('## Numerals shown on this figure')[0]
    listed=re.findall(r'^- (\d+)$',t.split('## Numerals shown on this figure')[1],re.M)
    used=set(re.findall(r'\b(\d{2})\b',body))
    print(os.path.basename(f),"listed",listed,"used",sorted(used,key=int),"extra_used",sorted(used-set(listed)),"unused_listed",sorted(set(listed)-used))
for f in sorted(glob.glob('draft/*.md'))+sorted(glob.glob('figures/*.md')):
    t=open(f).read()
    for bad in ['—','TODO','TBD','placeholder','[insert','XXX']:
        if bad in t: print("BAD",f,bad)
